sp_widget.css:
.tm-card{
    background:#ffffff;
    border-radius:20px;
    padding:24px;
    border:1px solid #E5E7EB;
    box-shadow:0 10px 30px rgba(15,23,42,.05);
}

.tm-header{
    display:flex;
    justify-content:space-between;
    align-items:center;
    margin-bottom:25px;
}

.tm-header h4{
    margin:0;
    font-size:18px;
    font-weight:700;
    color:#0F172A;
}

.tm-badge{
    background:#ECFDF5;
    color:#16A34A;
    padding:6px 12px;
    border-radius:30px;
    font-size:12px;
    font-weight:600;
}

.tm-donut-container{
    display:flex;
    justify-content:center;
    margin:20px 0;
}

.tm-donut{
    width:240px;
    height:240px;
    border-radius:50%;
    position:relative;
    transition:.3s;
}

.tm-donut:hover{
    transform:scale(1.03);
}

.tm-donut:before{
    content:'';
    position:absolute;
    width:150px;
    height:150px;
    background:#fff;
    border-radius:50%;
    top:50%;
    left:50%;
    transform:translate(-50%,-50%);
}

.tm-center{
    position:absolute;
    top:50%;
    left:50%;
    transform:translate(-50%,-50%);
    text-align:center;
    z-index:10;
}

.tm-total{
    font-size:40px;
    font-weight:800;
    color:#0F172A;
}

.tm-label{
    font-size:13px;
    color:#64748B;
}

.tm-rate{
    margin-top:8px;
    color:#16A34A;
    font-weight:700;
}

.tm-stats{
    display:grid;
    grid-template-columns:repeat(5,1fr);
    gap:10px;
    margin-top:25px;
}

.tm-stat{
    border-radius:14px;
    padding:12px;
    display:flex;
    align-items:center;
    gap:10px;
}

.tm-dot{
    width:12px;
    height:12px;
    border-radius:50%;
}

.tm-stat strong{
    display:block;
    font-size:18px;
}

.tm-stat small{
    color:#64748B;
}

.success{
    background:#F0FDF4;
}
.success .tm-dot{
    background:#22C55E;
}

.active{
    background:#EFF6FF;
}
.active .tm-dot{
    background:#3B82F6;
}

.warning{
    background:#FFFBEB;
}
.warning .tm-dot{
    background:#F59E0B;
}

.draft{
    background:#F5F3FF;
}
.draft .tm-dot{
    background:#A855F7;
}

.danger{
    background:#FEF2F2;
}
.danger .tm-dot{
    background:#EF4444;
}

@media(max-width:1200px){
    .tm-stats{
        grid-template-columns:repeat(2,1fr);
    }
}

sp_widget.script:
(function() {

    data.counts = {
        completed: 0,
        active: 0,
        paused: 0,
        draft: 0,
        cancelled: 0
    };

    var gr = new GlideRecord('x_snc_trackmed_medication_schedule_table');
    gr.query();

    while (gr.next()) {

        var state = gr.getValue('state');

        switch(state) {

            case 'completed':
                data.counts.completed++;
                break;

            case 'active':
                data.counts.active++;
                break;

            case 'paused':
                data.counts.paused++;
                break;

            case 'draft':
                data.counts.draft++;
                break;

            case 'cancelled':
                data.counts.cancelled++;
                break;
        }
    }

    data.total =
        data.counts.completed +
        data.counts.active +
        data.counts.paused +
        data.counts.draft +
        data.counts.cancelled;

    if (data.total == 0) {

        data.completedDeg = 0;
        data.activeDeg = 0;
        data.pausedDeg = 0;
        data.draftDeg = 0;
        data.completionRate = 0;
        return;
    }

    data.completedDeg =
        Math.round((data.counts.completed / data.total) * 360);

    data.activeDeg =
        data.completedDeg +
        Math.round((data.counts.active / data.total) * 360);

    data.pausedDeg =
        data.activeDeg +
        Math.round((data.counts.paused / data.total) * 360);

    data.draftDeg =
        data.pausedDeg +
        Math.round((data.counts.draft / data.total) * 360);

    data.completionRate =
        Math.round(
            (data.counts.completed / data.total) * 100
        );

})();
